// ---------------------------------------------------------------- the medals, a pop per tier (yours, on the sting bus)
// A Halo style pop: a click, a quick pitched bloop, a short chime of three harmonics. Each tier climbs a step (E3, G3, A3, B3, D4) and adds a
// layer: 2 a sub, 3 a second pop a fifth up, 4 a third pop and a low chord swell, 5 a low boom under all of it and a longer ring.
// Tier 1 DOUBLE KILL, 2 TRIPLE KILL, 3 MULTI KILL, 4 RAMPAGE, 5 UNSTOPPABLE (and the style medals, see SPK_MAP).
var SPK_MEDF=[164.8,196,220,246.9,293.7], SPK_MEDL=[0.36,0.45,0.55,0.8,1.05];
function spkMedal(a,OUT,vol,t,tier){
  var M, o, f=SPK_MEDF[tier-1], L=SPK_MEDL[tier-1], ring=0.22+0.08*tier, k, n;
  M=spkMaster(a,OUT,vol,t);
  spkTick(a,M,t,1800,1,0.012,0.1);
  n=(tier>=4)?3:((tier>=3)?2:1);
  for(k=0;k<n;k++){
    var fk=f*[1,1.5,2][k], at=t+k*0.075;
    spkOsc(a,M,{ty:'sine',f0:fk*2.2,f1:fk,dur:0.07,g:0.22,at:at,atk:0.002});
    spkOsc(a,M,{ty:'triangle',f0:fk,dur:ring,g:0.09,lp:1600,at:at+0.01,atk:0.003});
    spkOsc(a,M,{ty:'triangle',f0:fk*2,dur:ring*0.7,g:0.035,lp:2200,at:at+0.01,atk:0.003});
    o=spkOsc(a,M,{ty:'triangle',f0:fk*3,dur:ring*0.45,g:0.014,lp:2600,at:at+0.01,atk:0.003});
  }
  if(tier>=2) spkSub(a,M,f/2,f/4,0.18+0.04*tier,0.18,t);
  if(tier>=4){
    spkOsc(a,M,{ty:'sawtooth',f0:f/2,dur:L-0.1,g:0.04,lp:700,at:t+0.05,sh:'swell',pk:0.25});
    spkOsc(a,M,{ty:'sawtooth',f0:f*0.75,dur:L-0.1,g:0.035,lp:700,at:t+0.05,sh:'swell',pk:0.25});
  }
  if(tier>=5){
    spkSub(a,M,80,30,0.6,0.3,t);
    spkNoise(a,M,{at:t,dur:0.3,g:0.12,ft:'lowpass',f0:400,q:0.7,atk:0.002});
    o=spkMetal(a,M,f/2,t+0.24,0.8,[0.05,0.02,0.008]);
  }
  return spkH(M,o,t+L);
}
(function(){
  var i;
  for(i=1;i<=5;i++){
    (function(tier){
      var nm='medal'+tier;
      SPK_CAT[nm]='sting';
      SPK_INFO[nm]={grp:'medals',lab:'MEDAL tier '+tier+' ('+['DOUBLE KILL','TRIPLE KILL','MULTI KILL','RAMPAGE','UNSTOPPABLE'][tier-1]+')',len:SPK_MEDL[tier-1],kind:'synth',uses:[]};
      SPK_GEN[nm]=function(a,OUT,vol,t){ if(!spkGate('medal',0.05,t)) return null; return spkMedal(a,OUT,vol,t,tier); };
    })(i);
  }
})();

