// ================================================================ 4. playing a cue
// spkPlay(name,o): plays one cue now and returns its handle {g,o,end} (null when it did not play). o (all optional): ac an audio context,
// out the node to play into, t a start time, vol, wid, d. Inside the game the defaults are ac() and the cue's bus, sndBus(SPK_CAT[name]).
function spkPlay(name,o){
  var a, out, t;
  o=o||{};
  if(!SPK_GEN[name]) return null;
  if(typeof G==='object'&&G&&G.sim) return null;
  if(typeof NET==='object'&&NET&&NET.specTick) return null;
  a=o.ac||((typeof ac==='function')?ac():null); if(!a) return null;
  out=o.out||((typeof sndBus==='function')?sndBus(SPK_CAT[name]||'world'):null)||a.destination;
  t=(o.t!==undefined)?o.t:a.currentTime;
  try{ return SPK_GEN[name](a,out,(o.vol===undefined)?1:o.vol,t,o.wid,o.d); }catch(e){ return null; }
}
// the rings and the hearing range of the world cues that take the place of sfx('boom') (the same as boom's), and of the new world sounds
var SPK_NOISEMARK={
  debrisLand:{r:120,hear:1500}, airBoom:{r:120,hear:1500}, gateBreach:{r:120,hear:1500}, barrelBlast:{r:120,hear:1500}, barrelChain:{r:110,hear:1500},
  debrisFall:{r:60,hear:1400}, convoyRoll:{r:70,hear:1300}, coolantBurst:{r:80,hear:1200}, rampageRoar:{r:90,hear:1400}
};
// spkAdopt(): into the game's tables (SNDA_GEN, SND_CAT, NOISEMARK), never over a key the game already has. Returns how many cues it added.
function spkAdopt(){
  var k, n=0;
  if(typeof SNDA_GEN!=='object'||!SNDA_GEN||typeof SND_CAT!=='object'||!SND_CAT) return 0;
  for(k in SPK_GEN){ if(SNDA_GEN[k]===undefined){ SNDA_GEN[k]=SPK_GEN[k]; n++; } if(SND_CAT[k]===undefined) SND_CAT[k]=SPK_CAT[k]; }
  if(typeof NOISEMARK==='object'&&NOISEMARK) for(k in SPK_NOISEMARK) if(NOISEMARK[k]===undefined) NOISEMARK[k]=SPK_NOISEMARK[k];
  return n;
}

